-- Учитель+ — расширение демонстрационного каталога.
-- Скрипт идемпотентен: его можно запускать повторно в Supabase SQL Editor.

on conflict(id) do update set name=excluded.name,city=excluded.city,address=excluded.address;

on conflict(id) do update set school_id=excluded.school_id,name=excluded.name,subject=excluded.subject,category=excluded.category,initials=excluded.initials,bio=excluded.bio;

